#!/usr/bin/env bash
#
# A wizard walks a human through a manual procedure, step by step.
# Generated by the /wizard skill.
#
# Everything above the "STAGES" marker is the wizard library: do not hand-edit
# it. Author the per-step stages below the marker.

set -euo pipefail

# ──────────────────────────────────────────────────────────────────────────
# Wizard library: delightful, consistent UX, identical across every wizard.
# ──────────────────────────────────────────────────────────────────────────

if [[ -t 1 ]] && command -v tput >/dev/null 2>&1 && [[ "$(tput colors 2>/dev/null || echo 0)" -ge 8 ]]; then
  BOLD=$(tput bold); DIM=$(tput dim); RESET=$(tput sgr0)
  BLUE=$(tput setaf 4); GREEN=$(tput setaf 2); YELLOW=$(tput setaf 3)
else
  BOLD=""; DIM=""; RESET=""; BLUE=""; GREEN=""; YELLOW=""
fi

# Author sets this at the top of the stages section.
TOTAL_STAGES=0

_STAGE_INDEX=0
ENV_FILE="${ENV_FILE:-.env}"
WRITTEN_ENV=()    # KEYs written to ENV_FILE this run
WRITTEN_SECRET=() # secret NAMEs set this run
SKIPPED=()        # things we couldn't do (e.g. gh missing)

# _clear wipes the terminal so only the current step is on screen. No-op when
# output isn't a terminal, so piped logs stay readable.
_clear() {
  [[ -t 1 ]] || return 0
  if command -v tput >/dev/null 2>&1 && tput clear 2>/dev/null; then return 0; fi
  printf '\033[2J\033[3J\033[H'
}

# banner "Title" shows the opening frame: what this wizard does.
banner() {
  _clear
  printf '\n%s%s  %s%s\n' "$BOLD" "$BLUE" "$1" "$RESET"
  printf '%s  %s stages%s\n\n' "$DIM" "$TOTAL_STAGES" "$RESET"
  printf '%s  You drive the browser; this wizard tells you exactly what to do and\n' "$DIM"
  printf '  captures the values you copy back. Stop any time with Ctrl-C and re-run\n'
  printf '  later, since it remembers values already saved.%s\n' "$RESET"
  pause "Ready to start?"
}

# stage "Name" clears the screen, then announces a stage and shows progress.
# Clearing keeps only the current step on screen.
stage() {
  _clear
  _STAGE_INDEX=$((_STAGE_INDEX + 1))
  printf '\n%s%s▸ Stage %s/%s · %s%s\n' \
    "$BOLD" "$BLUE" "$_STAGE_INDEX" "$TOTAL_STAGES" "$1" "$RESET"
}

# say "..." prints a plain instruction line.
say()  { printf '  %s\n' "$1"; }
# step "..." is a numbered-feeling action the human takes in the browser.
step() { printf '  %s•%s %s\n' "$BLUE" "$RESET" "$1"; }
note() { printf '  %s%s%s\n' "$DIM" "$1" "$RESET"; }
warn() { printf '  %s⚠ %s%s\n' "$YELLOW" "$1" "$RESET"; }

# open_url URL opens it in the human's browser, cross-platform incl. WSL.
open_url() {
  local url="$1"
  printf '  %s↗ opening%s %s\n' "$GREEN" "$RESET" "$url"
  { if   command -v wslview     >/dev/null 2>&1; then wslview "$url"
    elif command -v explorer.exe >/dev/null 2>&1; then explorer.exe "$url"
    elif command -v xdg-open    >/dev/null 2>&1; then xdg-open "$url"
    elif command -v open        >/dev/null 2>&1; then open "$url"
    else false; fi
  } >/dev/null 2>&1 || warn "couldn't open a browser, so visit it manually: $url"
}

# pause "msg" waits for the human to confirm they've done the manual part.
pause() {
  printf '  %s%s%s ' "$DIM" "${1:-Press Enter to continue}" "$RESET"
  read -r _ || true
}

# confirm "question" is a y/N gate; returns success on yes.
confirm() {
  local reply=""
  printf '  %s? %s [y/N] ' "$YELLOW" "$1"
  read -r reply || true
  [[ "$reply" =~ ^[Yy] ]]
}

# _existing KEY: current value of KEY in ENV_FILE, if any, with write_env's single
# quotes or a plain dotenv double-quoted value undone.
_existing() {
  [[ -f "$ENV_FILE" ]] || return 1
  local line value sq="'\\''"; line=$(grep -E "^${1}=" "$ENV_FILE" | tail -n1) || return 1
  value="${line#*=}"
  if [[ "$value" == \'*\' ]]; then value="${value:1:${#value}-2}"; value="${value//"$sq"/\'}"
  elif [[ "$value" == \"*\" ]]; then
    value="${value:1:${#value}-2}"
    [[ "$value" == *[\\\$\"]* ]] && return 1   # escapes, $ or ": can't decode safely; ask again
  fi
  printf '%s' "$value"
}

# ask KEY "Prompt" reads a value into $KEY. Offers the existing .env value as
# a default on re-runs (Enter keeps it). Visible input (non-secret), edited
# with Readline. Fails at EOF with no input.
ask() {
  local key="$1" prompt="$2" current input s=$'\001' e=$'\002' p rc=0
  current=$(_existing "$key" || true)
  # Readline needs the colour codes wrapped in \001..\002 to place the cursor.
  p="  $s$BOLD$e$prompt$s$RESET$e "
  [[ -n "$current" ]] && p+="$s$DIM$e[Enter keeps current]$s$RESET$e "
  read -e -r -p "$p" input || rc=1
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# ask_secret KEY "Prompt" is like ask, but input is hidden.
ask_secret() {
  local key="$1" prompt="$2" current input rc=0
  current=$(_existing "$key" || true)
  if [[ -n "$current" ]]; then
    printf '  %s%s%s %s[Enter keeps current]%s ' "$BOLD" "$prompt" "$RESET" "$DIM" "$RESET"
  else
    printf '  %s%s%s ' "$BOLD" "$prompt" "$RESET"
  fi
  read -rs input || rc=1
  printf '\n'
  if (( rc )) && [[ -z "$input" ]]; then return 1; fi
  [[ -z "$input" && -n "$current" ]] && input="$current"
  printf -v "$key" '%s' "$input"
}

# write_env KEY VALUE upserts KEY='VALUE' into ENV_FILE (replaces any existing
# line) and sets $KEY. Idempotent. Creates ENV_FILE at mode 0600; writes through
# a symlink and keeps an existing file's mode.
write_env() {
  local key="$1" value="$2" tmp sq="'\\''"
  [[ -e "$ENV_FILE" ]] || (umask 077 && : > "$ENV_FILE")
  tmp=$(mktemp)
  grep -vE "^${key}=" "$ENV_FILE" > "$tmp" || true
  printf "%s='%s'\n" "$key" "${value//\'/$sq}" >> "$tmp"
  cat "$tmp" > "$ENV_FILE"
  rm -f "$tmp"
  printf -v "$key" '%s' "$value"
  WRITTEN_ENV+=("$key")
  printf '  %s✓ wrote%s %s → %s\n' "$GREEN" "$RESET" "$key" "$ENV_FILE"
}

# set_secret NAME VALUE sets a GitHub Actions repo secret via gh. Falls back
# to a warning (and records it) if gh is unavailable or unauthenticated.
set_secret() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if printf '%s' "$value" | gh secret set "$name" >/dev/null 2>&1; then
      WRITTEN_SECRET+=("$name")
      printf '  %s✓ set%s GitHub secret %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub secret $name (set it manually: gh secret set $name)")
  warn "skipped GitHub secret $name: gh not ready; set it later"
}

# set_var NAME VALUE sets a GitHub Actions repo variable (non-secret).
set_var() {
  local name="$1" value="$2"
  if command -v gh >/dev/null 2>&1 && gh auth status >/dev/null 2>&1; then
    if gh variable set "$name" --body "$value" >/dev/null 2>&1; then
      printf '  %s✓ set%s GitHub variable %s\n' "$GREEN" "$RESET" "$name"
      return
    fi
  fi
  SKIPPED+=("GitHub variable $name")
  warn "skipped GitHub variable $name, gh not ready; set it later"
}

# finish clears, then shows a closing summary of everything configured.
finish() {
  _clear
  printf '\n%s%s  ✓ Setup complete%s\n' "$BOLD" "$GREEN" "$RESET"
  (( ${#WRITTEN_ENV[@]} ))    && note "wrote ${#WRITTEN_ENV[@]} value(s) to $ENV_FILE: ${WRITTEN_ENV[*]}"
  (( ${#WRITTEN_SECRET[@]} )) && note "set ${#WRITTEN_SECRET[@]} GitHub secret(s): ${WRITTEN_SECRET[*]}"
  if (( ${#SKIPPED[@]} )); then
    printf '\n'; warn "still to do by hand:"
    for s in "${SKIPPED[@]}"; do note "  - $s"; done
  fi
  printf '\n'
}

# ──────────────────────────────────────────────────────────────────────────
# STAGES: author this section. One stage() per step the human takes.
# Replace the example below. Set TOTAL_STAGES to match the stages you write.
# Keep every stage inside run_wizard and the last line as is: bash then parses
# the whole file before the first prompt, so an edit mid-run can't break it.
# ──────────────────────────────────────────────────────────────────────────


# Staging wizard (#231, spec #219 Part B, ADR-0005): the steps only the human can take
# for staging. Run it once from the main checkout: bash scripts/staging-wizard.sh
#
# Secrets: typed values are read with ask_secret and piped on with printf (a builtin, so
# no argv); the generated one is piped straight out of its generator and never held.
# Vercel writes name Preview and the branch, nothing else.

# One place each. Every Vercel command below is built from these.
STAGING_BRANCH="redesign"
STAGING_FQDN="staging.winnies.christried.me"
DNS_ZONE="christried.me"
CNAME_TARGET="33f7f1db86eda8b6.vercel-dns-017.com"   # what Vercel asks for, written on issue #230; host `staging.winnies` in the zone christried.me
VERCEL_PROJECT="winnies"
VERCEL_SCOPE="christrieds-projects"
STAGING_DB_NAME="winnies_staging"

CNAME_HOST="${STAGING_FQDN%.$DNS_ZONE}"
VC=(-p "$VERCEL_PROJECT" --scope "$VERCEL_SCOPE")
VERCEL_WRITTEN=()   # Vercel variable NAMEs set this run
FORCE=()            # the replace flag, set only after a y/N that defaults to no

# preflight refuses a worktree, finds the tools and the login, and says what this does.
preflight() {
  local gd common
  gd=$(git rev-parse --git-dir) || { warn "Not inside the repository."; exit 1; }
  common=$(git rev-parse --git-common-dir) || { warn "Not inside the repository."; exit 1; }
  gd=$(cd "$gd" && pwd -P)
  common=$(cd "$common" && pwd -P)
  if [[ "$gd" != "$common" ]]; then
    if [[ "${STAGING_WIZARD_ALLOW_WORKTREE:-}" == "1" ]]; then
      warn "STAGING_WIZARD_ALLOW_WORKTREE=1 is set. That escape is for QA only: never set it for a real run."
    else
      warn "Run this from the main checkout: a worktree's .env is deleted with the worktree."
      note "(STAGING_WIZARD_ALLOW_WORKTREE=1 skips this check for QA only. Never set it for a real run.)"
      exit 1
    fi
  fi
  cd "$(git rev-parse --show-toplevel)"

  local tool
  for tool in vercel node; do
    command -v "$tool" >/dev/null 2>&1 || { warn "$tool is not installed or not on PATH."; exit 1; }
  done
  if ! command -v openssl >/dev/null 2>&1; then
    note "openssl not found: the generated secret will come from node's crypto instead."
  fi
  if ! vercel whoami >/dev/null 2>&1; then
    warn "Not signed in to Vercel. Run: vercel login, then run this wizard again."
    exit 1
  fi
}

# resolve_cname NAME prints the CNAME of NAME as seen through 1.1.1.1, lower-case, trailing
# dot trimmed, or nothing. Node's resolver, because Git Bash has no dig and the local
# resolver caches a miss.
resolve_cname() {
  node -e 'const {Resolver}=require("dns").promises; const r=new Resolver(); r.setServers(["1.1.1.1"]); r.resolveCname(process.argv[1]).then(a=>console.log(a.map(x=>x.toLowerCase().replace(/\.$/,"")).join(" ")),()=>{})' "$1" 2>/dev/null || true
}

# vercel_has NAME: 0 when Vercel lists NAME for Preview of the branch, 1 when it does not,
# 2 when Vercel could not be asked. The table also holds values (shortened): nothing from
# it is printed, only matched.
vercel_has() {
  local -a st
  set +e
  vercel env ls --environment preview --git-branch "$STAGING_BRANCH" "${VC[@]}" 2>/dev/null | tr -d '\r' | awk -v n="$1" '$1 == n && /Preview/ { f = 1 } END { exit !f }'
  st=("${PIPESTATUS[@]}")
  set -e
  if (( st[0] != 0 )); then return 2; fi
  return "${st[2]}"
}

# stop_here ends the run on a "no" at a write gate, saying what, if anything, changed.
stop_here() {
  if (( ${#VERCEL_WRITTEN[@]} )); then
    note "Stopped. Already set in Vercel this run: ${VERCEL_WRITTEN[*]}"
  else
    note "Nothing was changed."
  fi
  exit 0
}

# plan_preview_var NAME: detect, offer replace (default no), then the gate that shows the
# exact command with a placeholder. Returns 0 to write, 1 to skip. A "no" at the gate ends the run.
plan_preview_var() {
  local name="$1" rc=0
  FORCE=()
  vercel_has "$name" || rc=$?
  case "$rc" in
    0)
      say "$name is already set for Preview of $STAGING_BRANCH."
      if confirm "Replace it with a new value?"; then
        FORCE=(--force)
      else
        note "Kept as it is."
        return 1
      fi ;;
    1) ;;
    *) warn "Could not ask Vercel what is set (try: vercel whoami). Nothing was changed."; exit 1 ;;
  esac
  printf '\n'
  say "This will run, with the real value piped in:"
  note "<value> | vercel env add $name --environment preview --git-branch \"$STAGING_BRANCH\" --sensitive --yes ${FORCE[*]-} -p $VERCEL_PROJECT --scope $VERCEL_SCOPE"
  confirm "Write this?" || stop_here
  return 0
}

# check_written NAME re-runs the detect: not listed means the write failed.
check_written() {
  local rc=0
  vercel_has "$1" || rc=$?
  if (( rc == 0 )); then
    VERCEL_WRITTEN+=("$1")
    printf '  %s✓ set%s %s for Preview of %s (Vercel lists it)\n' "$GREEN" "$RESET" "$1" "$STAGING_BRANCH"
  else
    warn "$1 is not listed for Preview of $STAGING_BRANCH, so the write failed. Stopping; nothing is retried."
    exit 1
  fi
}

write_failed() {
  warn "Vercel refused $1 (its message is above). Stopping; nothing is retried."
  exit 1
}

# gen_secret prints 32 random bytes as base64 (44 characters, no newline) and nothing else.
gen_secret() {
  if command -v openssl >/dev/null 2>&1; then
    openssl rand -base64 32 | tr -d '\n'
  else
    node -e 'process.stdout.write(require("crypto").randomBytes(32).toString("base64"))'
  fi
}

# valid_db_url checks $STAGING_DATABASE_URL without printing it.
valid_db_url() {
  local dev
  case "$STAGING_DATABASE_URL" in
    postgres://*|postgresql://*) ;;
    *) warn "That is not a postgres:// or postgresql:// URL, so it was not used."; return 1 ;;
  esac
  dev=$(_existing DATABASE_URL || true)
  if [[ -n "$dev" && "$STAGING_DATABASE_URL" == "$dev" ]]; then
    warn "That is the DATABASE_URL in $ENV_FILE (the development database), so it was not used."
    return 1
  fi
  if [[ "$STAGING_DATABASE_URL" != *-pooler* ]]; then
    warn "The host has no -pooler in it, so this is not the pooled string Connect shows by default."
    confirm "Use it anyway?" || return 1
  fi
  if [[ "$STAGING_DATABASE_URL" != *"/$STAGING_DB_NAME"* ]]; then
    warn "The URL does not name the database $STAGING_DB_NAME."
    confirm "Use it anyway?" || return 1
  fi
  return 0
}

# dns_choice asks what to do about a name that does not resolve yet. EOF quits.
dns_choice() {
  local reply=""
  printf '  %s? [c] check again  [s] skip with a warning  [q] quit: ' "$YELLOW"
  read -r reply || reply="q"
  case "$reply" in
    [Cc]*) CHOICE="check" ;;
    [Ss]*) CHOICE="skip" ;;
    *)     CHOICE="quit" ;;
  esac
}

# ──────────────────────────────────────────────────────────────────────────

run_wizard() {

TOTAL_STAGES=5

trap 'unset STAGING_DATABASE_URL VERCEL_AUTOMATION_BYPASS_SECRET' EXIT

preflight

say ""
note "This wizard writes only Preview variables of the branch $STAGING_BRANCH in Vercel, and one"
note "line in $ENV_FILE. It never touches the production environment, its variables or its domain."
note "Secrets are read hidden and piped on: none is printed, logged or left in a file."
pause "Press Enter to continue."

banner "Staging setup"

# ── 1. CNAME ──────────────────────────────────────────────────────────────
stage "CNAME at Namecheap"
if [[ -z "$CNAME_TARGET" ]]; then
  warn "#230 has not written the record yet: CNAME_TARGET at the top of this file is empty."
  note "Nothing was changed."
  exit 1
fi
want=$(printf '%s' "$CNAME_TARGET" | tr 'A-Z' 'a-z')
want="${want%.}"
if [[ "$(resolve_cname "$STAGING_FQDN")" == "$want" ]]; then
  # A re-run: the record is already in place, so there is nothing to do at Namecheap.
  say "$STAGING_FQDN already resolves to $want, nothing to do at Namecheap."
else
  say "Point $STAGING_FQDN at Vercel with one DNS record."
  open_url "https://ap.www.namecheap.com/domains/list"
  step "Manage $DNS_ZONE > Advanced DNS > Add New Record, then enter:"
  note "    Type    CNAME"
  note "    Host    $CNAME_HOST"
  note "    Target  $CNAME_TARGET"
  note "    TTL     Automatic"
  step "Save the record (the green tick)."
  pause "Press Enter when the record is saved."
  while true; do
    got=$(resolve_cname "$STAGING_FQDN")
    if [[ "$got" == "$want" ]]; then
      printf '  %s✓ resolves%s %s → %s\n' "$GREEN" "$RESET" "$STAGING_FQDN" "$got"
      break
    fi
    if [[ -z "$got" ]]; then
      warn "$STAGING_FQDN does not resolve to a CNAME yet (checked through 1.1.1.1). DNS can take a few minutes."
    else
      warn "$STAGING_FQDN resolves to $got, not $want."
      note "Vercel's Domains page may ask for a different target: change CNAME_TARGET at the top of this file, tell issue #230, run again."
    fi
    dns_choice
    case "$CHOICE" in
      check) ;;
      skip) SKIPPED+=("CNAME: not checked ($STAGING_FQDN did not resolve to $want)"); break ;;
      *) note "Nothing was changed."; exit 1 ;;
    esac
  done
fi
say "Asking Vercel what it thinks of the domain (read-only, best effort):"
verify_out=$(vercel domains verify "$STAGING_FQDN" "${VC[@]}" 2>&1 || true)
{ grep -E '^  "(status|message|hint)"' <<<"$verify_out" || printf '%s\n' "$verify_out" | head -n 15; } | sed 's/^ */    /' || true
pause "Press Enter for the next stage."

# ── 2. Neon branch ────────────────────────────────────────────────────────
stage "Neon branch for staging"
say "Staging gets its own Neon branch with its own empty database, so it holds none of the live site's rows."
if confirm "Done in an earlier run?"; then
  note "Taking your word for it."
else
  open_url "https://console.neon.tech"
  step "Open the project for this app > Branches > Create branch, name it: staging (any parent)."
  step "On that branch only: Databases > create a new, empty database named $STAGING_DB_NAME."
  step "Then delete the database the branch copied from its parent."
  warn "Check the branch name at the top of the Neon page before you delete anything."
  note "Deleting a database on the staging branch changes nothing on its parent."
  note "Why: the branch must hold no live rows (#219, B3), and no tables either: the first staging build"
  note "creates the schema from the committed migrations (#233) and fails on a database that has them."
  pause "Press Enter when the staging branch holds only the empty $STAGING_DB_NAME."
  say "I cannot check this: nothing here can look inside the Neon branch."
  if ! confirm "Does the staging branch hold none of the live site's rows?"; then
    warn "Stopping: fix the branch first, then run the wizard again."
    note "Nothing was written."
    exit 1
  fi
fi
SKIPPED+=("Neon branch: its rows were not checked (you confirmed it holds none of the live site's)")
pause "Press Enter for the next stage."

# ── 3. Discord redirect ───────────────────────────────────────────────────
stage "Discord redirect"
say "Staging signs in with the existing Discord app, which must accept staging's callback."
if confirm "Done in an earlier run?"; then
  note "Taking your word for it."
else
  open_url "https://discord.com/developers/applications"
  step "Open the existing app > OAuth2 > Redirects > Add Redirect, exactly:"
  note "    https://$STAGING_FQDN/api/auth/callback/discord"
  step "Save Changes. Leave the redirects already there alone."
  pause "Press Enter when it is saved."
fi
say "I could not check this: Discord has no read API for it that works without a secret."
note "#234 signs in on staging and proves it."
SKIPPED+=("Discord redirect: not checked (#234 signs in on staging and proves it)")
pause "Press Enter for the next stage."

# ── 4. Vercel variables ───────────────────────────────────────────────────
stage "Vercel variables for Preview of $STAGING_BRANCH"
say "DATABASE_URL (you paste it) and BETTER_AUTH_SECRET (generated here, never shown),"
say "both for Preview deployments of the branch $STAGING_BRANCH only."

if plan_preview_var DATABASE_URL; then
  open_url "https://console.neon.tech"
  step "Open the staging branch > Connect, and pick the database $STAGING_DB_NAME."
  step "Copy the pooled connection string, the one Connect shows by default (its host has -pooler)."
  while true; do
    ask_secret STAGING_DATABASE_URL "Paste the connection string (hidden):" || { warn "No input. Nothing more was written."; exit 1; }
    if valid_db_url; then break; fi
  done
  if printf '%s' "$STAGING_DATABASE_URL" | vercel env add DATABASE_URL --environment preview --git-branch "$STAGING_BRANCH" --sensitive --yes ${FORCE[@]+"${FORCE[@]}"} "${VC[@]}"; then
    unset STAGING_DATABASE_URL
  else
    unset STAGING_DATABASE_URL
    write_failed DATABASE_URL
  fi
  check_written DATABASE_URL
fi

if plan_preview_var BETTER_AUTH_SECRET; then
  say "Generating 32 random bytes and piping them straight to Vercel: you will not see them."
  if gen_secret | vercel env add BETTER_AUTH_SECRET --environment preview --git-branch "$STAGING_BRANCH" --sensitive --yes ${FORCE[@]+"${FORCE[@]}"} "${VC[@]}"; then
    :
  else
    write_failed BETTER_AUTH_SECRET
  fi
  check_written BETTER_AUTH_SECRET
fi
pause "Press Enter for the next stage."

# ── 5. Protection Bypass for Automation ───────────────────────────────────
stage "Protection Bypass for Automation"
say "Lets the staging checks reach the protected preview. It goes into $ENV_FILE only."
if [[ -f "$ENV_FILE" ]] && grep -q '^VERCEL_AUTOMATION_BYPASS_SECRET=' "$ENV_FILE"; then
  say "VERCEL_AUTOMATION_BYPASS_SECRET is already in $ENV_FILE."
  if confirm "Replace it with a new value?"; then
    ASK_BYPASS=1
  else
    note "Kept as it is."
    ASK_BYPASS=0
  fi
else
  ASK_BYPASS=1
fi
if (( ASK_BYPASS )); then
  open_url "https://vercel.com/$VERCEL_SCOPE/$VERCEL_PROJECT/settings/deployment-protection"
  step "Find the 'Protection Bypass for Automation' section."
  step "Add a secret (or use the one shown) and copy it."
  warn "Do not change the project's protection level."
  while true; do
    ask_secret VERCEL_AUTOMATION_BYPASS_SECRET "Paste the bypass secret (hidden):" || { warn "No input."; exit 1; }
    [[ -n "$VERCEL_AUTOMATION_BYPASS_SECRET" ]] && break
    warn "Empty: paste the secret."
  done
  write_env VERCEL_AUTOMATION_BYPASS_SECRET "$VERCEL_AUTOMATION_BYPASS_SECRET"
  unset VERCEL_AUTOMATION_BYPASS_SECRET
fi
pause "Press Enter to finish."

finish
if (( ${#VERCEL_WRITTEN[@]} )); then
  note "set in Vercel for Preview of $STAGING_BRANCH: ${VERCEL_WRITTEN[*]}"
  printf '\n'
fi
}

run_wizard "$@"; exit
